CREATE TABLE resources (
  id                         TEXT PRIMARY KEY,
  title                      TEXT NOT NULL,
  type                       TEXT NOT NULL CHECK (type IN
                               ('Lecture Note','Past Question','Assignment Material','Textbook','Revision Sheet','Other')),
  department                 TEXT NOT NULL,
  course                     TEXT NOT NULL,
  level                      TEXT NOT NULL CHECK (level IN ('100','200','300','400','500','600')),
  semester                   TEXT NOT NULL CHECK (semester IN ('First','Second')),
  session                    TEXT NOT NULL,                -- e.g. "2024/2025"

  uploader_id                TEXT NOT NULL REFERENCES users(id),

  file_name                  TEXT NOT NULL,
  file_url                   TEXT NOT NULL,
  cloudinary_public_id       TEXT NOT NULL,
  cloudinary_resource_type   TEXT NOT NULL DEFAULT 'raw' CHECK (cloudinary_resource_type IN ('raw','image')),
  preview_image_public_id    TEXT,
  preview_type               TEXT NOT NULL DEFAULT 'none' CHECK (preview_type IN ('image','text','none')),
  preview_snippet            TEXT NOT NULL DEFAULT '',
  preview_message            TEXT NOT NULL DEFAULT '',

  file_size_bytes            INTEGER NOT NULL,
  file_extension              TEXT NOT NULL,
  pages                      INTEGER NOT NULL DEFAULT 1,

  status                     TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  rejection_reason           TEXT NOT NULL DEFAULT '',

  downloads                  INTEGER NOT NULL DEFAULT 0,

  reviewed_by                TEXT REFERENCES users(id),
  reviewed_at                TEXT,
  description                TEXT NOT NULL DEFAULT '',

  created_at                 TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at                 TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
, file_hash TEXT, bounty_id TEXT);
INSERT INTO "resources" ("id","title","type","department","course","level","semester","session","uploader_id","file_name","file_url","cloudinary_public_id","cloudinary_resource_type","preview_image_public_id","preview_type","preview_snippet","preview_message","file_size_bytes","file_extension","pages","status","rejection_reason","downloads","reviewed_by","reviewed_at","description","created_at","updated_at","file_hash","bounty_id") VALUES('6a98d1927ed778a25a5f30c8','CSC 206 (COMPUTER ARCHITECTURE)','Lecture Note','Computer Science','CSC206','200','Second','2025/2026','6a961b27eac5ee842e72ccfe','CSC 206 (COMPUTER ARCHITECTURE).pdf','https://res.cloudinary.com/zbijzuhl/raw/upload/v1788400017/sharef_resources/z99a4bcsxscoofuaugmo.pdf','sharef_resources/z99a4bcsxscoofuaugmo.pdf','raw','sharef_resources_preview/hbmtd2imhogsfdtyr8pq','image','','',130564,'pdf',12,'approved','',13,'6a50f4d975e3029e6c610529','2026-09-03T01:51:12.877Z','','2026-09-03T01:46:58.663Z','2026-09-26T06:45:22.907Z',NULL,NULL);
INSERT INTO "resources" ("id","title","type","department","course","level","semester","session","uploader_id","file_name","file_url","cloudinary_public_id","cloudinary_resource_type","preview_image_public_id","preview_type","preview_snippet","preview_message","file_size_bytes","file_extension","pages","status","rejection_reason","downloads","reviewed_by","reviewed_at","description","created_at","updated_at","file_hash","bounty_id") VALUES('6a98e1fe35dd4dd79c5b7cc2','Summary of CSC212','Revision Sheet','Computer Science','CSC212','200','Second','2025/2026','6a961b27eac5ee842e72ccfe','Summary of CSC212.docx','https://res.cloudinary.com/zbijzuhl/raw/upload/v1788404222/sharef_resources/edxtjwztzklrdyol2tnf.docx','sharef_resources/edxtjwztzklrdyol2tnf.docx','raw',NULL,'text','Summary of CSC212 Connection-less service (HTTP) - Connection seizes to exist once the server sends a response. HTTP - Hyper Text Transfer Protocol, It formats how information is communicated between web browsers and web servers. Protocol - This are rules that defines how a web browser and a web server communicates. Client - It is an application that request the service of another application. Server - It is an application that provides services and resources to the client Web application - It is an application that runs on the browser. Web document is a file that has the extension .html or .htm. Web element or tag - This are characters that tells the browser how to display its content. It is written in angular brackets. Categorizes of Web element (tag) Block element - This are elements that appear on a new line and take the entire width of the screen. E.g, p, section, div, h1 to h6. Inline (non-block) element - They don’t start on a new line and are wrapped around each other and don’t…','',14829,'docx',2,'approved','',3,'6a50f4d975e3029e6c610529','2026-09-04T05:34:19.425Z','Applications of Computer Programming and Web Development','2026-09-03T02:57:02.756Z','2026-09-12T08:10:45.236Z',NULL,NULL);
INSERT INTO "resources" ("id","title","type","department","course","level","semester","session","uploader_id","file_name","file_url","cloudinary_public_id","cloudinary_resource_type","preview_image_public_id","preview_type","preview_snippet","preview_message","file_size_bytes","file_extension","pages","status","rejection_reason","downloads","reviewed_by","reviewed_at","description","created_at","updated_at","file_hash","bounty_id") VALUES('6a9a57f764e74fc14aac415e','Summary of CSC210','Revision Sheet','Computer Science','CSC210','200','Second','2025/2026','6a961b27eac5ee842e72ccfe','Summary of CSC210.docx','https://res.cloudinary.com/zbijzuhl/raw/upload/v1788499958/sharef_resources/dshnxo0sfeezqfp1ejxl.docx','sharef_resources/dshnxo0sfeezqfp1ejxl.docx','raw',NULL,'text','Summary of CSC210 Course Outline Data Management Database System DBMS Architecture Data Modelling Data Management Data management is the process of collecting, organizing, storing, securing and managing data to ensure its availabilty, credibility, and usability. Data: This are raw, unprocessed facts. Information: This are output of processed data, used for decision making. Techniques of data collection Questionaires Field Online Sources Key Aspect of Data Management Data Governance: This are policies that guides the use and transfer of data. Data Security: It protects data against against breaches through authentication, encryption and access control. Data Quality Management: It ensures quality by doing reular cleanup to ensure quality. Data Integration: It’s the combination of data from different sources efficiently. Data Lifecycle Management: It is the managing of data from point of collection to deletion. Data Management Technology Database Management System (DBMS) : It is a central…','',21817,'docx',3,'approved','',2,'6a50f4d975e3029e6c610529','2026-09-04T05:34:10.320Z','Introduction to Database Management.','2026-09-04T05:32:39.696Z','2026-10-07T02:09:01.495Z',NULL,NULL);
INSERT INTO "resources" ("id","title","type","department","course","level","semester","session","uploader_id","file_name","file_url","cloudinary_public_id","cloudinary_resource_type","preview_image_public_id","preview_type","preview_snippet","preview_message","file_size_bytes","file_extension","pages","status","rejection_reason","downloads","reviewed_by","reviewed_at","description","created_at","updated_at","file_hash","bounty_id") VALUES('6a9e61f1b23f9b0582546bc7','INF 202 (Human Computer Interaction)','Lecture Note','Computer Science','INF202','200','Second','2025/2026','6a961b27eac5ee842e72ccfe','INF 202 (Human Computer Interaction).pdf','https://res.cloudinary.com/zbijzuhl/raw/upload/v1788764657/sharef_resources/mbssbhmiv5u7bc0acp7s.pdf','sharef_resources/mbssbhmiv5u7bc0acp7s.pdf','raw',NULL,'text','Human Computer Interaction (HCI) Human Computer Interaction Human Computer Interaction (HCI) is a multi-disciplinary field of study focusing on the design of computer technology and, in particular, the interaction between humans and computers. This field is concerned with the design, implementation, and evaluation of interactive computing systems. Human: A human is the individual user or group of users. Computer: Any technology ranging from embedded systems to desktop computers. Interaction: Parts or points of the computer that the user makes contact with. Goal of HCI The goal of','',182352,'pdf',24,'approved','',5,'6a50f4d975e3029e6c610529','2026-09-08T21:48:37.307Z','Covers the important topics in Human and Computer Interaction.','2026-09-07T07:04:17.730Z','2026-10-07T02:29:02.476Z',NULL,NULL);
