CREATE TABLE announcements (
  id                  TEXT PRIMARY KEY,
  title               TEXT NOT NULL,
  message             TEXT NOT NULL,
  target_departments  TEXT NOT NULL DEFAULT '[]',   -- JSON array; empty array = "everyone"
  target_levels       TEXT NOT NULL DEFAULT '[]',   -- JSON array; empty array = "everyone"
  created_by          TEXT NOT NULL REFERENCES users(id),
  recipient_count     INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "announcements" ("id","title","message","target_departments","target_levels","created_by","recipient_count","created_at","updated_at") VALUES('6a81dedb1a72f3444522e4a0','Schedule maintenance this weekend','We want to kindly inform you all that from 10 am - 12pm there will be a period of outage, and the system won''t be accessible during this time, please bear with us, thank you for you cooperation. We will get the system up and running as soon as we can.','["Computer science"]','["200"]','6a50f4d975e3029e6c610529',0,'2026-08-16T16:01:31.465Z','2026-08-16T16:01:31.465Z');
INSERT INTO "announcements" ("id","title","message","target_departments","target_levels","created_by","recipient_count","created_at","updated_at") VALUES('6aa3f17d261bf00f0f3c94e1','Happy Holidays From Sharef','I wish everyone of you that took part in the semesters exams success, And I''m proud to announce to all of you that sharef will be going live for the 2026/2027 academic session. I you have any information or compliant kindly send a message via email to Sharef@gmail.com. Thank you.','[]','[]','6a50f4d975e3029e6c610529',7,'2026-09-11T12:18:05.179Z','2026-09-11T12:18:05.179Z');
INSERT INTO "announcements" ("id","title","message","target_departments","target_levels","created_by","recipient_count","created_at","updated_at") VALUES('6aa3f304261bf00f0f3c94e9','Collaboration between NACOS and Sharef','The Nacos team will be collaborating with Sharef on an academic event, Stay tuned for more information.','["Computer Science"]','[]','6a50f4d975e3029e6c610529',2,'2026-09-11T12:24:36.860Z','2026-09-11T12:24:36.860Z');
CREATE TABLE deleted_account_logs (
  id                          TEXT PRIMARY KEY,
  full_name                   TEXT NOT NULL,
  email                       TEXT NOT NULL,
  matric_number                TEXT NOT NULL DEFAULT '',
  university                  TEXT NOT NULL DEFAULT '',
  department                  TEXT NOT NULL DEFAULT '',
  level                       TEXT NOT NULL DEFAULT '',
  account_status              TEXT NOT NULL DEFAULT 'active',
  joined_at                   TEXT,
  wallet_balance_at_deletion   REAL NOT NULL DEFAULT 0,
  uploads_count                INTEGER NOT NULL DEFAULT 0,
  total_deposited              REAL NOT NULL DEFAULT 0,
  total_spent                  REAL NOT NULL DEFAULT 0,
  created_at                  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) -- doubles as "deletedAt"
);
INSERT INTO "deleted_account_logs" ("id","full_name","email","matric_number","university","department","level","account_status","joined_at","wallet_balance_at_deletion","uploads_count","total_deposited","total_spent","created_at") VALUES('6aa5d0d8b847fc81b525a9a4','Tequilla','tequillamonkey67@gmail.com','TEST/2026/002','Test University','Nursing','300','active','2026-07-18T02:50:39.800Z',1500,0,1500,0,'2026-09-12T22:23:20.516Z');
CREATE TABLE notifications (
  id                     TEXT PRIMARY KEY,
  resource_id            TEXT REFERENCES resources(id),
  announcement_id        TEXT REFERENCES announcements(id),
  deleted_account_log_id TEXT REFERENCES deleted_account_logs(id),
  recipient_id           TEXT REFERENCES users(id),  -- NULL = shared admin feed
  type                   TEXT NOT NULL DEFAULT 'new_upload' CHECK (type IN
                           ('new_upload','resource_approved','resource_rejected','announcement','account_deleted')),
  unread                 INTEGER NOT NULL DEFAULT 1,  -- 0/1 boolean
  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
